INSERT INTO `clinics` (`id`, `name`, `status`, `created_at`, `updated_at`, `template`, `old_clinic_id`) VALUES
(3, 'Gynecology/Obstetrics', 1, NULL, NULL, '<div>\n	<tr>\n        <td contenteditable=\"false\">Biodata(Name, Sex, Age,etc)</td>\n        <td contenteditable=\"false\"><span\n                style=\"border:1px solid black; min-width: 300px; min-height: 100px; display:inline-block;\"\n                contenteditable=\"true\"></span></td>\n    </tr>\n	<h1 contenteditable=\"false\">Reproductive profile &nbsp; &nbsp; <button type=\"button\" class=\"btn btn-secondary\" onclick=\"toggle_group(\'gr1\')\">Click to expand</button></h1>\n	<table class=\"table\">\n		<thead>\n			<tr class = \"gr1\">\n				<td contenteditable=\"false\">\n					<h3 contenteditable=\"false\">Parity(1,2,3,4,5.....)</h3>\n				</td>\n				<td contenteditable=\"false\">\n					<span style=\"border:1px solid black; min-width: 100px; display:inline-block;\"\n						contenteditable=\"true\"></span>\n				</td>\n			</tr>\n			<tr class = \"gr1\">\n				<td contenteditable=\"false\">\n					<h3 contenteditable=\"false\">Gravidity(1,2,3,4,5.....)</h3>\n				</td>\n				<td contenteditable=\"false\">\n					<span style=\"border:1px solid black; min-width: 100px; display:inline-block;\"\n						contenteditable=\"true\"></span>\n				</td>\n			</tr>\n		</thead>\n	</table>\n\n\n	<h3 contenteditable=\"false\" class = \"gr1\">\n		<span>Last child birth (LCB) (years):</span>\n		<span style=\"border:1px solid black; min-width: 100px; display:inline-block;\" contenteditable=\"true\">\n		</span>\n	</h3>\n	<h3 contenteditable=\"false\" class = \"gr1\">\n		<span>Last menstrual period (LMP):</span>\n		<span style=\"border:1px solid black; min-width: 100px; display:inline-block;\" contenteditable=\"true\"></span>\n	</h3>\n	<h3 contenteditable=\"false\" class = \"gr1\">\n		<span>Expected date of delivery:</span>\n		<span style=\"border:1px solid black; min-width: 100px; display:inline-block;\" contenteditable=\"true\"></span>\n	</h3>\n	<h3 contenteditable=\"false\" class = \"gr1\">\n		<span>Estimated gestational age :</span>\n		<span 